mapper.insert:
INSERT INTO coreerp.daily_summaries(business_date,source_version,run_id,sales_amount,sales_shipments,shipped_quantity,purchases,ordered_quantity,receipts,receipt_quantity)
WITH sales AS (
  SELECT coalesce(sum(oi.unit_price*si.quantity),0) amount,count(DISTINCT s.id) shipments,coalesce(sum(si.quantity),0) quantity

), purchases AS (
  SELECT count(DISTINCT o.id) count,coalesce(sum(i.quantity),0) quantity
  FROM coreerp.purchase_orders o JOIN coreerp.purchase_order_items i ON i.order_id=o.id
  WHERE o.status!='CANCELLED' AND o.created_at >= #{from} AND o.created_at < #{to}
), receipts AS (
  SELECT count(DISTINCT r.id) count,coalesce(sum(i.quantity),0) quantity
  FROM coreerp.goods_receipts r JOIN coreerp.goods_receipt_items i ON i.receipt_id=r.id
  WHERE r.created_at >= #{from} AND r.created_at < #{to}
) SELECT #{date},#{version},#{id},s.amount,s.shipments,s.quantity,p.count,p.quantity,r.count,r.quantity
FROM sales s CROSS JOIN purchases p CROSS JOIN receipts r
